    assertSame(serverCl, manager.getClassLoader("/org/apache/cayenne/access/DataContext.class"));
    assertSame(diCl, manager.getClassLoader("/org/apache/cayenne/di/Injector.class"));
    assertSame(diCl, manager.getClassLoader("org/apache/cayenne/di/Injector.class"));
}

